async function reports(){const c=$('.content'),year=new Date().getFullYear();let d=await api({action:'reports',start_date:`${year}-01-01`,end_date:new Date().toISOString().slice(0,10)});const draw=()=>{const p=d.selected_period;c.innerHTML=page('Reports','Current account counts and selected-period operational reporting.','')+`<section class="card"><div class="card-body"><form id="reportRange" class="saas-form-grid"><label><span>Start Date</span><input type="date" name="start_date" value="${esc(d.period.start_date)}"></label><label><span>End Date</span><input type="date" name="end_date" value="${esc(d.period.end_date)}"></label><div class="form-action-cell"><button class="btn btn-orange">Run Report</button></div></form></div></section><section class="owner-report-label">Current account counts</section><section class="metrics"><article class="metric-card"><div class="metric-label">Drivers</div><div class="metric-value">${d.current.drivers}</div></article><article class="metric-card"><div class="metric-label">Programs</div><div class="metric-value">${d.current.programs}</div></article></section><section class="owner-report-label">Selected reporting period</section><section class="metrics owner-metrics-six"><article class="metric-card"><div class="metric-label">Testing Orders</div><div class="metric-value">${p.testing_orders.length}</div></article><article class="metric-card"><div class="metric-label">Results</div><div class="metric-value">${p.results.length}</div></article><article class="metric-card"><div class="metric-label">Compliance Cases</div><div class="metric-value">${p.compliance_cases.length}</div></article><article class="metric-card"><div class="metric-label">Documents</div><div class="metric-value">${p.documents.length}</div></article><article class="metric-card"><div class="metric-label">Selections</div><div class="metric-value">${p.selections.length}</div></article><article class="metric-card"><div class="metric-label">Audit Events</div><div class="metric-value">${p.audit.length}</div></article></section><section class="card"><div class="card-head"><div><h2>Exports</h2><span>CSV exports use the currently selected reporting period.</span></div></div><div class="card-body owner-export-grid"><button class="btn btn-outline" data-export="testing_orders">Testing CSV</button><button class="btn btn-outline" data-export="results">Results CSV</button><button class="btn btn-outline" data-export="compliance_cases">Compliance CSV</button><button class="btn btn-outline" data-export="documents">Documents CSV</button><button class="btn btn-outline" data-export="selections">Selections CSV</button>${p.audit.length?'<button class="btn btn-outline" data-export="audit">Audit CSV</button>':''}${d.advanced_enabled?'<button class="btn btn-orange" id="misReport">Download DOT MIS CSV</button>':''}</div></section>`;$('#reportRange').onsubmit=async e=>{e.preventDefault();try{d=await api({action:'reports',...Object.fromEntries(new FormData(e.currentTarget))});draw();status('Report period updated.')}catch(err){status(err.message,'error')}};$$('[data-export]').forEach(b=>b.onclick=()=>csv(p[b.dataset.export],`owner-${b.dataset.export}-${d.period.start_date}-${d.period.end_date}`));if($('#misReport'))$('#misReport').onclick=async()=>{try{const {data,error}=await supabase.functions.invoke('workforce-owner-mis-report',{body:{year:new Date(d.period.end_date).getFullYear()}});if(error)throw error;csv([...(data.testing||[]).map(x=>({section:'MIS_TESTING_DATA',...x})),...(data.post_accidents||[]).map(x=>({section:'POST_ACCIDENT_AUDIT_APPENDIX',...x}))],`owner-dot-mis-${new Date(d.period.end_date).getFullYear()}`)}catch(err){status(err.message,'error')}}};draw()}

async function billing(){const d=await api({action:'billing'}),c=$('.content'),s=d.subscription;c.innerHTML=page('Plan & Billing','Review your active plan, invoice history, balances, and provider-issued payment links.')+`<section class="metrics"><article class="metric-card"><div class="metric-label">Plan</div><div class="metric-value owner-metric-text">${esc(s?.plans?.name||'No plan')}</div></article><article class="metric-card"><div class="metric-label">Subscription</div><div class="metric-value owner-metric-text">${esc(title(s?.status||'—'))}</div></article><article class="metric-card"><div class="metric-label">Renewal</div><div class="metric-value owner-metric-text">${fmt(s?.renewal_date)}</div></article><article class="metric-card"><div class="metric-label">Open Balance</div><div class="metric-value owner-metric-text">${money(d.invoices.reduce((n,x)=>n+Number(x.amount_due||0),0))}</div></article></section>`+table(['Invoice','Issued','Due','Total','Balance','Status','Action'],d.invoices.map(x=>`<tr><td><strong>${esc(x.invoice_number)}</strong></td><td>${fmt(x.issued_at)}</td><td>${fmt(x.due_at)}</td><td>${money(x.total)}</td><td>${money(x.amount_due)}</td><td>${pill(x.status)}</td><td><div class="row-actions">${x.view_url?`<a class="org-action" href="${esc(x.view_url)}" target="_blank" rel="noopener">View</a>`:''}${x.payment_url&&Number(x.amount_due||0)>0?`<a class="btn btn-orange btn-small" href="${esc(x.payment_url)}" target="_blank" rel="noopener">Pay</a>`:''}</div></td></tr>`),'No invoices have been issued.');wireTables()}

async function notifications(){let d=await api({action:'notifications'}),c=$('.content');const draw=()=>{c.innerHTML=page('Notifications & Messages','Review Owner-Operator scoped delivery history and communicate with screenings4u support staff.','<a class="btn btn-outline" href="support.html">Support Tickets</a>')+`<div class="grid grid-2"><section class="card"><div class="card-head"><div><h2>Messages</h2><span>Account-specific conversations</span></div></div><div class="card-body"><form id="messageForm" class="saas-form"><input type="hidden" name="thread_id"><label><span>Subject</span><input name="subject" required></label><label><span>Message</span><textarea name="body" rows="5" required></textarea></label><div class="saas-actions"><button class="btn btn-orange">Send Message</button></div></form></div></section><section class="card"><div class="card-head"><div><h2>Recent Threads</h2><span>Latest account conversations</span></div></div><div class="card-body status-list">${d.threads.slice(0,8).map(t=>`<div class="status-row"><div><strong>${esc(t.subject)}</strong><small>${(t.owner_messages||[]).length} message(s) · ${dt(t.last_message_at)}</small></div><div class="row-actions">${pill(t.status)}<button type="button" class="org-action" data-reply-thread="${t.id}">Reply</button></div></div>`).join('')||empty('No message threads yet.')}</div></section></div><section class="card owner-section-gap"><div class="card-head"><div><h2>Notification Delivery History</h2><span>Only notifications scoped to your account/user/contact address are shown.</span></div></div>${table(['Queued','Event','Channel','Subject','Status','Delivered'],d.notifications.map(x=>`<tr><td>${dt(x.queued_at)}</td><td>${esc(title(x.event_type))}</td><td>${esc(title(x.channel))}</td><td><strong>${esc(x.subject||'—')}</strong></td><td>${pill(x.status)}</td><td>${dt(x.delivered_at)}</td></tr>`),'No Owner-Operator notifications yet.')}</section>`;wireTables();$$('[data-reply-thread]').forEach(b=>b.onclick=()=>{const t=d.threads.find(x=>x.id===b.dataset.replyThread),f=$('#messageForm');f.thread_id.value=t?.id||'';f.subject.value=t?.subject||'';f.body.focus();status(`Replying to ${t?.subject||'message thread'}.`,'success')});$('#messageForm').onsubmit=async e=>{e.preventDefault();try{await api({action:'send_message',...Object.fromEntries(new FormData(e.currentTarget))});d=await api({action:'notifications'});draw();status('Message sent.')}catch(err){status(err.message,'error')}}};draw()}

function staffForm(x={}){return `${formHead(x.id?'Edit Staff Access':'Invite Staff',x.id?'Update staff status and result visibility.':'Invite read-oriented staff to this Owner-Operator workspace.')}<form id="staffForm" class="owner-modal-body saas-form"><input type="hidden" name="id" value="${esc(x.id||'')}"><div class="saas-form-grid">${x.id?'':`<label><span>First Name</span><input name="first_name"></label><label><span>Last Name</span><input name="last_name"></label><label class="saas-wide"><span>Email *</span><input name="email" type="email" required></label>`}<label><span>Result Access</span><select name="result_access">${['none','summary','authorized'].map(v=>option(v,title(v),x.result_access||'summary')).join('')}</select></label>${x.id?`<label><span>Status</span><select name="status">${['active','suspended','revoked'].map(v=>option(v,title(v),x.status||'active')).join('')}</select></label>`:''}</div><div class="saas-notice">Staff are read-only for drivers, programs, pools/selections, testing, compliance, documents, and reports. Billing, account profile editing, audit history, staff management, and operational write actions remain Owner-Operator Administrator only.</div><div class="saas-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-orange">${x.id?'Save Access':'Send Invitation'}</button></div></form>`}
async function staff(){let d=await membersApi({action:'list'}),c=$('.content');const draw=()=>{c.innerHTML=page('Staff & Access','Invite read-oriented staff and control account/result visibility.','<button class="btn btn-orange" id="inviteStaff">Invite Staff</button>')+`<div class="saas-notice">Owner-Operator Staff can review operational records but cannot change your company profile, create or edit testing/compliance records, manage billing, sign Owner-Operator legal packets, view Audit History, or manage other users.</div>`+table(['Staff','Email','Portal Role','Result Access','Status','Actions'],(d.staff||[]).map(x=>`<tr><td><strong>${esc(x.full_name||'Staff User')}</strong></td><td>${esc(x.email)}</td><td>Owner-Operator Staff</td><td>${pill(x.result_access)}</td><td>${pill(x.status)}</td><td><button class="org-action" data-edit-staff="${x.id}">Edit</button></td></tr>`),'No staff access records yet.');wireTables();$('#inviteStaff').onclick=()=>open({});$$('[data-edit-staff]').forEach(b=>b.onclick=()=>open((d.staff||[]).find(x=>x.id===b.dataset.editStaff)||{}))};const open=x=>{const m=modal(staffForm(x));$('#staffForm',m).onsubmit=async e=>{e.preventDefault();const member=Object.fromEntries(new FormData(e.currentTarget));try{await membersApi({action:x.id?'save':'invite',member});m.classList.remove('open');d=await membersApi({action:'list'});draw();status(x.id?'Staff access updated.':'Staff invitation sent.')}catch(err){status(err.message,'error')}}};draw()}

async function auditPage(){const d=await api({action:'audit'}),c=$('.content');c.innerHTML=page('Audit History','Permitted activity history for this Owner-Operator organization. Sensitive before/after payloads, IP address, and user-agent data are not exposed.')+table(['Date / Time','Action','Resource','Resource ID','Actor'],d.audit.map(x=>`<tr><td>${dt(x.event_at)}</td><td><strong>${esc(title(x.action))}</strong></td><td>${esc(title(x.resource_type))}</td><td>${esc(x.resource_id||'—')}</td><td>${esc(x.actor_user_id||'System')}</td></tr>`),'No audit history.');wireTables()}

async function support(){let d=await supportApi({action:'list'}),c=$('.content');const draw=()=>{c.innerHTML=page('Support','Create and review support requests for your Owner-Operator workspace.')+`<div class="grid grid-2"><section class="card"><div class="card-head"><div><h2>New Support Request</h2><span>Send an issue or question to screenings4u.</span></div></div><div class="card-body"><form id="supportForm" class="saas-form"><div class="saas-form-grid"><label><span>Category</span><select name="category"><option value="general">General</option><option value="testing">Testing</option><option value="compliance">Compliance</option><option value="documents">Documents</option><option value="billing">Billing</option><option value="technical">Technical</option></select></label><label><span>Priority</span><select name="priority"><option value="normal">Normal</option><option value="low">Low</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label class="saas-wide"><span>Subject</span><input name="subject" required></label><label class="saas-wide"><span>Message</span><textarea name="message" rows="6" required></textarea></label></div><div class="saas-actions"><button class="btn btn-orange">Create Ticket</button></div></form></div></section><section class="card"><div class="card-head"><div><h2>Support Guide</h2><span>What to include</span></div></div><div class="card-body"><div class="saas-notice">Include the affected driver, testing order, document, invoice, or case number when applicable. Do not place passwords or full sensitive result data in a support ticket.</div></div></section></div><section class="card owner-section-gap"><div class="card-head"><div><h2>Ticket History</h2><span>Your organization’s support requests.</span></div></div>${table(['Ticket','Created','Category','Subject','Priority','Status'],(d.tickets||[]).map(x=>`<tr><td><strong>${esc(x.ticket_number)}</strong></td><td>${dt(x.created_at)}</td><td>${esc(title(x.category))}</td><td>${esc(x.subject)}</td><td>${pill(x.priority)}</td><td>${pill(x.status)}</td></tr>`),'No support tickets yet.')}</section>`;wireTables();$('#supportForm').onsubmit=async e=>{e.preventDefault();try{await supportApi({action:'create',...Object.fromEntries(new FormData(e.currentTarget))});d=await supportApi({action:'list'});draw();status('Support ticket created.')}catch(err){status(err.message,'error')}}};draw()}

const handlers={'dashboard.html':dashboard,'profile.html':profile,'driver.html':drivers,'programs.html':programs,'consortium.html':consortium,'testing.html':testing,'post-accident.html':postAccident,'results.html':results,'compliance.html':compliance,'rtd-follow-up.html':rtd,'documents.html':documents,'reports.html':reports,'billing.html':billing,'notifications.html':notifications,'staff.html':staff,'audit.html':auditPage,'support.html':support};

(async()=>{
 ctx=await portalReady;if(!ctx)return;
 // Live owner context is authoritative for permissions/entitlements and avoids stale shell cache during plan changes.
 try{live=await api({action:'context'});ctx={...ctx,permissions:live.permissions||ctx.permissions,entitlements:live.entitlements||ctx.entitlements,subscription:live.subscription||ctx.subscription}}catch(e){console.error(e)}
 nav();
 const feature={'driver.html':'employee_management','programs.html':'programs','consortium.html':'random_pool','testing.html':'testing_orders','post-accident.html':'testing_orders','results.html':'results_summary','compliance.html':'compliance','rtd-follow-up.html':'compliance','documents.html':'documents','reports.html':'standard_reports','audit.html':'audit_history'}[current()];
 if(feature&&!ent(feature)){ $('.content').innerHTML=page('Feature Not Included','This page is not enabled for the current Owner-Operator plan.')+`<section class="card"><div class="card-body">${empty('This feature is not enabled for your current plan.')}</div></section>`;return }
 if((current()==='profile.html'||current()==='staff.html'||current()==='audit.html'||current()==='notifications.html'||current()==='support.html')&&!can('users.manage')){$('.content').innerHTML=page('Owner-Operator Workspace','Your role does not include administrator access to this page.')+empty('Administrator access is required.');return}
 if(current()==='billing.html'&&!can('billing.read')){$('.content').innerHTML=page('Billing','Your role does not include billing access.')+empty('Billing access is not available.');return}
 try{await (handlers[current()]||dashboard)()}catch(e){console.error(e);$('.content').innerHTML=page('Owner-Operator Workspace','This page could not be loaded.')+`<section class="card"><div class="card-body"><div class="saas-notice error">${esc(e.message||'Unable to load this page.')}</div></div></section>`}
})();
